JS_EVENT_FMT = "<IhBB"
JS_EVENT_SIZE = struct.calcsize(JS_EVENT_FMT)
EV_FF = 0x15
FF_RUMBLE = 0x50
EVIOCSFF = 0x40304580

class LinuxControllerPoller:
    def __init__(self):
        self.lock = threading.Lock()
        self.running = False
        self.fds = [None, None, None, None]
        self.connected = [False, False, False, False]
        self.buttons = [{} for _ in range(4)]
        self.axes = [{} for _ in range(4)]
        self.pkt_hz = [0, 0, 0, 0]
        self.trig_hz = [0, 0, 0, 0]
        self.input_pulse = [False, False, False, False]
        self.ff_fds = {}
        self.ff_ids = {}

    def start(self):
        if self.running:
            return
        with self.lock:
            self.input_pulse = [False, False, False, False]
        self.running = True
        threading.Thread(target=self._loop, daemon=True).start()

    def stop(self):
        self.running = False
        self.stop_all_rumble()
        for i in range(4):
            if self.fds[i] is not None:
                try:
                    os.close(self.fds[i])
                except OSError:
                    pass
                self.fds[i] = None

    def _find_event_path(self, port):
        matches = glob.glob(f"/sys/class/input/js{port}/device/event*")
        if not matches:
            return None
        ev_name = os.path.basename(matches[0])
        ev_path = f"/dev/input/{ev_name}"
        return ev_path if os.path.exists(ev_path) else None

    def set_rumble(self, port, strong_mag, weak_mag, duration_ms):
        ev_path = self._find_event_path(port)
        if not ev_path:
            return False, "No FF event node"
        try:
            fd = self.ff_fds.get(port)
            if fd is None:
                fd = os.open(ev_path, os.O_RDWR)
                self.ff_fds[port] = fd
            eff_id = self.ff_ids.get(port, -1)
            # struct ff_effect (48 bytes on 64-bit Linux): type(H), id(h), direction(H), trigger(HH), replay(HH), rumble(HH) + padding
            eff = bytearray(48)
            struct.pack_into("<HhHHHHHH", eff, 0, FF_RUMBLE, eff_id, 0, 0, 0, duration_ms, 0, strong_mag)
            struct.pack_into("<H", eff, 16, weak_mag)
            fcntl.ioctl(fd, EVIOCSFF, eff)
            eff_id = struct.unpack_from("<h", eff, 2)[0]
            self.ff_ids[port] = eff_id
            play_val = 1 if (strong_mag > 0 or weak_mag > 0) else 0
            ev = struct.pack("@llHHi", 0, 0, EV_FF, eff_id, play_val)
            os.write(fd, ev)
            return True, "ACTIVE" if play_val else "IDLE"
        except Exception:
            return False, "NO FF"

    def stop_all_rumble(self):
        for port in list(self.ff_fds.keys()):
            try:
                self.set_rumble(port, 0, 0, 10)
            except Exception:
                pass
            try:
                os.close(self.ff_fds[port])
            except Exception:
                pass
        self.ff_fds.clear()
        self.ff_ids.clear()

    def _loop(self):
        pkt_counts = [0, 0, 0, 0]
        trig_counts = [0, 0, 0, 0]
        prev_trig = [{2: False, 5: False} for _ in range(4)]
        prev_hat = [{6: False, 7: False} for _ in range(4)]
        prev_lstick = [False, False, False, False]
        prev_rstick = [False, False, False, False]
        cur_axes = [{0: 0, 1: 0, 3: 0, 4: 0} for _ in range(4)]
        engage_sq = 14745 * 14745  # 45% radial deadzone engage
        release_sq = 9830 * 9830   # 30% radial hysteresis release
        last_win = time.monotonic()
        while self.running:
            any_open = False
            for i in range(4):
                dev = f"/dev/input/js{i}"
                if self.fds[i] is None:
                    if os.path.exists(dev):
                        try:
                            self.fds[i] = os.open(dev, os.O_RDONLY | os.O_NONBLOCK)
                        except OSError:
                            self.fds[i] = None
                if self.fds[i] is not None:
                    any_open = True
                    try:
                        while True:
                            data = os.read(self.fds[i], JS_EVENT_SIZE)
                            if not data or len(data) < JS_EVENT_SIZE:
                                break
                            _ts, val, etype, num = struct.unpack(JS_EVENT_FMT, data)
                            is_init = bool(etype & 0x80)
                            real_type = etype & 0x7F
                            if real_type == 1:
                                with self.lock:
                                    prev_b = self.buttons[i].get(num, False)
                                    now_b = (val != 0)
                                    self.buttons[i][num] = now_b
                                    if (not is_init) and now_b and (not prev_b):
                                        self.input_pulse[i] = True
                                pkt_counts[i] += 1
                            elif real_type == 2:
                                pulse = False
                                if num in (0, 1):
                                    cur_axes[i][num] = val
                                    mag_sq = cur_axes[i][0] * cur_axes[i][0] + cur_axes[i][1] * cur_axes[i][1]
                                    if prev_lstick[i]:
                                        if mag_sq < release_sq:
                                            prev_lstick[i] = False
                                    elif mag_sq > engage_sq:
                                        prev_lstick[i] = True
                                        if not is_init:
                                            pulse = True
                                elif num in (3, 4):
                                    cur_axes[i][num] = val
                                    mag_sq = cur_axes[i][3] * cur_axes[i][3] + cur_axes[i][4] * cur_axes[i][4]
                                    if prev_rstick[i]:
                                        if mag_sq < release_sq:
                                            prev_rstick[i] = False
                                    elif mag_sq > engage_sq:
                                        prev_rstick[i] = True
                                        if not is_init:
                                            pulse = True
                                elif num in (2, 5):
                                    t_on = (val > 0)
                                    if (not is_init) and t_on and (not prev_trig[i][num]):
                                        pulse = True
                                    prev_trig[i][num] = t_on
                                elif num in (6, 7):
                                    h_on = (abs(val) > 16000)
                                    if (not is_init) and h_on and (not prev_hat[i][num]):
                                        pulse = True
                                    prev_hat[i][num] = h_on
                                with self.lock:
                                    self.axes[i][num] = val
                                    if pulse:
                                        self.input_pulse[i] = True
                                pkt_counts[i] += 1
                                if num in (2, 3, 4, 5):
                                    trig_counts[i] += 1
                    except BlockingIOError:
                        pass
                    except OSError:
                        try:
                            os.close(self.fds[i])
                        except OSError:
                            pass
                        self.fds[i] = None
                        prev_trig[i] = {2: False, 5: False}
                        prev_hat[i] = {6: False, 7: False}
                        prev_lstick[i] = False
                        prev_rstick[i] = False
                        cur_axes[i] = {0: 0, 1: 0, 3: 0, 4: 0}
                        with self.lock:
                            self.buttons[i].clear()
                            self.axes[i].clear()
                            self.input_pulse[i] = False
                with self.lock:
                    self.connected[i] = (self.fds[i] is not None)

            now = time.monotonic()
            if now - last_win >= 0.5:
                secs = max(0.05, now - last_win)
                with self.lock:
                    for i in range(4):
                        self.pkt_hz[i] = int(round(pkt_counts[i] / secs))
                        self.trig_hz[i] = int(round(trig_counts[i] / secs))
                        pkt_counts[i] = 0
                        trig_counts[i] = 0
                last_win = now

            time.sleep(0.005 if any_open else 0.25)

def is_installed():
    return os.path.exists(UDEV_GC) or os.path.exists(os.path.join(INSTALL_ROOT, "installed.json"))

def run_elevated(shell_cmd):
    if os.geteuid() == 0:
        return subprocess.run(["bash", "-c", shell_cmd], capture_output=True, text=True)
    if shutil.which("pkexec"):
        return subprocess.run(["pkexec", "bash", "-c", shell_cmd], capture_output=True, text=True)
    return subprocess.run(["sudo", "bash", "-c", shell_cmd], capture_output=True, text=True)

def detect_linux_dark_mode():
    if "dark" in os.environ.get("GTK_THEME", "").lower():
        return True
    try:
        out = subprocess.run(
            ["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"],
            capture_output=True, text=True, timeout=1
        ).stdout.lower()
        if "dark" in out:
            return True
    except Exception:
        pass
    try:
        out = subprocess.run(
            ["gsettings", "get", "org.gnome.desktop.interface", "gtk-theme"],
            capture_output=True, text=True, timeout=1
        ).stdout.lower()
        if "dark" in out:
            return True
    except Exception:
        pass
    kde_cfg = os.path.expanduser("~/.config/kdeglobals")
    if os.path.exists(kde_cfg):
        try:
            with open(kde_cfg, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    if line.lower().startswith("colorscheme=") and "dark" in line.lower():
                        return True
        except Exception:
            pass
    return False

class AnimatedSettingsButton(tk.Canvas):
    def __init__(self, parent, command):
        super().__init__(parent, width=90, height=26, highlightthickness=1, bd=0, cursor="hand2")
        self._cmd = command
        self._angle = 0.0
        self._target = 0.0
        self._hovered = False
        self._active = False
        self._anim_id = None
        self._palette = ("#F8FAFC", "#EEF2FF", "#334155", "#CBD5E1", "#4F46E5", "#FFFFFF", "#4F46E5")
        self.bind("<Enter>", self._on_enter)
        self.bind("<Leave>", self._on_leave)
        self.bind("<Button-1>", self._on_click)
        self._draw()

    def set_state(self, active, palette):
        self._active = active
        self._palette = palette
        self._target = 90.0 if (self._hovered or self._active) else 0.0
        self._ensure_anim()
        self._draw()

    def _on_enter(self, _e):
        self._hovered = True
        self._target = 90.0
        self._ensure_anim()
        self._draw()

    def _on_leave(self, _e):
        self._hovered = False
        self._target = 90.0 if self._active else 0.0
        self._ensure_anim()
        self._draw()

    def _on_click(self, _e):
        if self._cmd:
            self._cmd()

    def _ensure_anim(self):
        if self._anim_id is None:
            self._anim_id = self.after(16, self._step)

    def _step(self):
        self._anim_id = None
        diff = self._target - self._angle
        if abs(diff) < 0.8:
            self._angle = self._target
            self._draw()
            return
        self._angle += diff * 0.25
        self._draw()
        self._anim_id = self.after(16, self._step)

    def _draw(self):
        bg, hov_bg, fg, border, act_bg, act_fg, accent = self._palette
        cur_bg = act_bg if self._active else (hov_bg if self._hovered else bg)
        cur_fg = act_fg if self._active else fg
        icon_col = act_fg if self._active else (accent if self._hovered else fg)
        self.configure(bg=cur_bg, highlightbackground=act_bg if self._active else border)
        self.delete("all")
        cx, cy = 15.0, 13.0
        rad_off = math.radians(self._angle)
        for i in range(8):
            a = rad_off + i * (math.pi / 4.0)
            x1, y1 = cx + math.cos(a) * 4.2, cy + math.sin(a) * 4.2
            x2, y2 = cx + math.cos(a) * 6.8, cy + math.sin(a) * 6.8
            self.create_line(x1, y1, x2, y2, fill=icon_col, width=1.6, capstyle="round")
        self.create_oval(cx - 4.2, cy - 4.2, cx + 4.2, cy + 4.2, outline=icon_col, width=1.5, fill=cur_bg)
        self.create_oval(cx - 1.9, cy - 1.9, cx + 1.9, cy + 1.9, outline=icon_col, width=1.2, fill=cur_bg)
        self.create_text(27, 13, text="Settings", anchor="w", fill=cur_fg, font=("Sans", 8, "bold"))


