    def on_close(self):
        self.poller.stop()
        self.destroy()

    def select_port(self, port):
        self.stop_rumble()
        self.selected_port = port

    def test_rumble(self, strong_mag, weak_mag, dur_ms):
        if self.rumble_timer_id is not None:
            try:
                self.after_cancel(self.rumble_timer_id)
            except Exception:
                pass
            self.rumble_timer_id = None
        ok, status = self.poller.set_rumble(self.selected_port, strong_mag, weak_mag, dur_ms)
        self.lbl_r_state.configure(text="5.0s" if (ok and (strong_mag > 0 or weak_mag > 0)) else status)
        if ok and (strong_mag > 0 or weak_mag > 0):
            self.rumble_timer_id = self.after(dur_ms + 50, self.stop_rumble)

    def stop_rumble(self):
        if self.rumble_timer_id is not None:
            try:
                self.after_cancel(self.rumble_timer_id)
            except Exception:
                pass
            self.rumble_timer_id = None
        self.poller.stop_all_rumble()
        self.lbl_r_state.configure(text="IDLE")

    def set_tester_visible(self, show):
        self.tester_visible = show
        self.log_box.pack_forget()
        self.settings_frame.pack_forget()
        self.tester_frame.pack_forget()
        if self.tester_visible:
            self.settings_visible = False
            self.btn_tester.configure(text="Log")
            self.geometry("540x610")
            self.tester_frame.pack(fill="both", expand=True)
            self.poller.start()
            self.poll_tester_ui()
        else:
            self.poller.stop()
            self.btn_tester.configure(text="Test Pad")
            self.geometry("540x430")
            self.log_box.pack(fill="both", expand=True)
        self.apply_theme()

    def toggle_tester(self):
        self.set_tester_visible(not self.tester_visible)

    def poll_tester_ui(self):
        if not self.tester_visible:
            return
        with self.poller.lock:
            conn = list(self.poller.connected)
            pulses = list(self.poller.input_pulse)
            self.poller.input_pulse = [False, False, False, False]
            all_btns = [dict(self.poller.buttons[i]) for i in range(4)]
            all_axes = [dict(self.poller.axes[i]) for i in range(4)]
            all_pkt_hz = list(self.poller.pkt_hz)
            all_trig_hz = list(self.poller.trig_hz)

        switch_to = None
        for i in range(4):
            if conn[i] and i != self.selected_port and pulses[i]:
                switch_to = i
                break
        if switch_to is not None:
            self.select_port(switch_to)
        elif not conn[self.selected_port]:
            for i in range(4):
                if conn[i]:
                    self.select_port(i)
                    break

        p = self.selected_port
        is_conn = conn[p]
        btns = all_btns[p]
        axes = all_axes[p]
        pkt_hz = all_pkt_hz[p]
        trig_hz = all_trig_hz[p]

        border = "#334155" if self.dark_mode else "#E2E8F0"
        pill_bg = "#0F172A" if self.dark_mode else "#F1F5F9"
        pill_fg = "#94A3B8" if self.dark_mode else "#475569"
        accent = "#6366F1" if self.dark_mode else "#4F46E5"

        for i in range(4):
            sel = (i == p)
            if conn[i]:
                bg = "#10B981" if sel else ("#064E3B" if self.dark_mode else "#D1FAE5")
                fg = "#FFFFFF" if sel else ("#A7F3D0" if self.dark_mode else "#065F46")
                self.port_btns[i].configure(text=f"* P{i+1}", bg=bg, fg=fg, highlightbackground="#10B981")
            else:
                self.port_btns[i].configure(text=f"P{i+1}", bg=pill_bg, fg=pill_fg, highlightbackground=accent if sel else border)

        if is_conn:
            self.lbl_poll.configure(text=f"Poll: {pkt_hz} Hz  |  Trig: {trig_hz} Hz", fg=accent if (pkt_hz or trig_hz) else pill_fg)
        else:
            self.lbl_poll.configure(text="No controller connected", fg=pill_fg)

        pressed = []
        for idx, (bname, bnum) in enumerate(self.btn_specs):
            on = bool(is_conn and btns.get(bnum, False))
            if bname == "UP" and axes.get(7, 0) < -16000: on = True
            if bname == "DOWN" and axes.get(7, 0) > 16000: on = True
            if bname == "LEFT" and axes.get(6, 0) < -16000: on = True
            if bname == "RIGHT" and axes.get(6, 0) > 16000: on = True
            if on:
                pressed.append(bname)
                col = "#10B981" if idx == 0 else ("#DC2626" if idx == 1 else ("#7C3AED" if idx == 4 else accent))
                self.btn_labels[idx].configure(bg=col, fg="#FFFFFF", highlightbackground=col)
            else:
                self.btn_labels[idx].configure(bg=pill_bg, fg=pill_fg, highlightbackground=border)

        if is_conn:
            self.lbl_pad_hint.configure(text=(f"Port {p+1} Active: " + ", ".join(pressed)) if pressed else f"Port {p+1} Connected — Press buttons, squeeze L/R triggers, or test rumble.")
        else:
            self.lbl_pad_hint.configure(text="Waiting for /dev/input/js0..js3. Plug controller into Mayflash W012 (Wii U / NS).")

        # Draw sticks
        lx = (axes.get(0, 0) / 32767.0) if is_conn else 0.0
        ly = (axes.get(1, 0) / 32767.0) if is_conn else 0.0
        rx = (axes.get(3, 0) / 32767.0) if is_conn else 0.0
        ry = (axes.get(4, 0) / 32767.0) if is_conn else 0.0
        self._draw_sticks(lx, ly, rx, ry, is_conn)

        # Normalize L/R triggers (-32767..32767 -> 0..255)
        raw_lt = axes.get(2, -32767) if is_conn else -32767
        raw_rt = axes.get(5, -32767) if is_conn else -32767
        lt = max(0, min(255, int(round((raw_lt + 32767) * 255.0 / 65534.0)))) if is_conn else 0
        rt = max(0, min(255, int(round((raw_rt + 32767) * 255.0 / 65534.0)))) if is_conn else 0
        lp, rp = int(round(lt * 100 / 255.0)), int(round(rt * 100 / 255.0))
        lclk, rclk = (lt >= 248), (rt >= 248)
        self.lbl_lt.configure(text=f"L Trigger: {lt:03d} ({lp}%)" + (" [CLICK]" if lclk else ""))
        self.lbl_rt.configure(text=f"R Trigger: {rt:03d} ({rp}%)" + (" [CLICK]" if rclk else ""))
        self._draw_trig(self.cv_lt, lt, lclk)
        self._draw_trig(self.cv_rt, rt, rclk)

        self.after(35, self.poll_tester_ui)

    def _draw_sticks(self, lx, ly, rx, ry, active):
        c = self.stick_canvas
        c.delete("all")
        ring_bg = "#0F172A" if self.dark_mode else "#F8FAFC"
        ring_bd = "#475569" if self.dark_mode else "#CBD5E1"
        cross = "#334155" if self.dark_mode else "#E2E8F0"
        lbl_fg = "#94A3B8" if self.dark_mode else "#64748B"
        for cx, sx, sy, title, dot_col in [
            (36, lx, ly, "Main Stick", "#6366F1" if active else "#94A3B8"),
            (114, rx, ry, "C-Stick", "#F59E0B" if active else "#94A3B8"),
        ]:
            cy, r = 34, 28
            c.create_oval(cx - r, cy - r, cx + r, cy + r, fill=ring_bg, outline=ring_bd, width=1.5)
            c.create_line(cx - r + 3, cy, cx + r - 3, cy, fill=cross)
            c.create_line(cx, cy - r + 3, cx, cy + r - 3, fill=cross)
            mag = math.hypot(sx, sy)
            if mag > 1.0:
                sx, sy = sx / mag, sy / mag
            dx, dy = cx + sx * (r - 5), cy + sy * (r - 5)
            c.create_oval(dx - 4, dy - 4, dx + 4, dy + 4, fill=dot_col, outline="")
            c.create_text(cx, cy + r + 10, text=title, fill=lbl_fg, font=("Sans", 7, "bold"))

    def _draw_trig(self, cv, val, clicked):
        cv.delete("all")
        w = max(cv.winfo_width(), 200)
        h = max(cv.winfo_height(), 14)
        fill_col = "#10B981" if clicked else ("#6366F1" if self.dark_mode else "#4F46E5")
        fw = int(round((w * val) / 255.0))
        if fw > 0:
            cv.create_rectangle(0, 0, fw, h, fill=fill_col, outline="")

    def toggle_settings(self):
        self.settings_visible = not self.settings_visible
        self.log_box.pack_forget()
        self.settings_frame.pack_forget()
        self.tester_frame.pack_forget()
        if self.tester_visible:
            self.tester_visible = False
