        else:
            self.geometry("540x430")
            self.log_box.pack(fill="both", expand=True)
        self.apply_theme()

    def _parse_ver(self, tag):
        try:
            clean = (tag or "").strip().lstrip("vV").split("-")[0]
            parts = [int(x) for x in clean.split(".")[:3]]
            while len(parts) < 3:
                parts.append(0)
            return tuple(parts)
        except Exception:
            return (0, 0, 0)

    def check_updates_async(self):
        if self.checking_update or self.downloading_update:
            return
        self.checking_update = True
        self.btn_check_upd.configure(state="disabled")
        self.btn_dl_upd.pack_forget()
        self.lbl_s_upd.configure(text="Checking GitHub Releases for Vivimagic GC Suite updates...")

        def _worker():
            msg = ""
            show_dl = False
            tag = ""
            sh_url = ""
            page_url = "https://github.com/Vivimagic/GameCube-Bridge-Studio/releases"
            try:
                req = urllib.request.Request(
                    "https://api.github.com/repos/Vivimagic/GameCube-Bridge-Studio/releases/latest",
                    headers={"User-Agent": "Vivimagic-GC-Suite/2.0.0", "Accept": "application/vnd.github+json"},
                )
                with urllib.request.urlopen(req, timeout=10) as resp:
                    data = json.loads(resp.read().decode("utf-8", errors="replace"))
                tag = str(data.get("tag_name") or "").strip()
                if data.get("html_url"):
                    page_url = str(data["html_url"])
                for asset in data.get("assets") or []:
                    u = str(asset.get("browser_download_url") or "")
                    if u.lower().endswith(".sh"):
                        sh_url = u
                        break
                if self._parse_ver(tag) > (2, 0, 0):
                    msg = f"Update available: {tag} — click Download & Update."
                    show_dl = True
                else:
                    msg = f"You are up to date (Installed: v2.0.0" + (f", Latest: {tag}" if tag else "") + ")."
                    show_dl = bool(sh_url)
            except Exception as exc:
                msg = f"Could not check automatically ({exc})."
                show_dl = True

            def _done():
                self.checking_update = False
                self.latest_tag = tag
                self.latest_sh_url = sh_url
                self.latest_page_url = page_url
                self.lbl_s_upd.configure(text=msg)
                self.btn_check_upd.configure(state="normal")
                if show_dl:
                    self.btn_dl_upd.configure(text="Download & Update" if sh_url else "Open Releases")
                    self.btn_dl_upd.pack(side="left", padx=(6, 0))
            self.after(0, _done)

        threading.Thread(target=_worker, daemon=True).start()

    def download_update_async(self):
        if self.downloading_update:
            return
        if not self.latest_sh_url:
            webbrowser.open(self.latest_page_url)
            return
        self.downloading_update = True
        self.btn_check_upd.configure(state="disabled")
        self.btn_dl_upd.configure(state="disabled")
        self.lbl_s_upd.configure(text=f"Downloading update {self.latest_tag}...")

        def _worker():
            dl_dir = os.path.expanduser("~/Downloads")
            os.makedirs(dl_dir, exist_ok=True)
            out_path = os.path.join(dl_dir, "Vivimagic-GC-Suite-Linux-Update.sh")
            err = ""
            try:
                req = urllib.request.Request(self.latest_sh_url, headers={"User-Agent": "Vivimagic-GC-Suite/2.0.0"})
                with urllib.request.urlopen(req, timeout=60) as resp, open(out_path, "wb") as out_f:
                    shutil.copyfileobj(resp, out_f)
                os.chmod(out_path, 0o755)
            except Exception as exc:
                err = str(exc)

            def _done():
                self.downloading_update = False
                self.btn_check_upd.configure(state="normal")
                self.btn_dl_upd.configure(state="normal")
                if not err and os.path.exists(out_path):
                    self.lbl_s_upd.configure(text=f"Saved update to ~/Downloads — launching updated suite...")
                    try:
                        subprocess.Popen(["bash", out_path])
                        self.on_close()
                    except Exception as lex:
                        self.lbl_s_upd.configure(text=f"Saved to {out_path} (launch error: {lex}).")
                else:
                    self.lbl_s_upd.configure(text=f"Download failed: {err}")
            self.after(0, _done)

        threading.Thread(target=_worker, daemon=True).start()

