    def set_status_box(self, kind, title, desc):
        self.status_kind = kind or "info"
        self.status_title = title or ""
        self.status_desc = desc or ""
        if self.dark_mode:
            themes = {
                "success": ("#064E3B", "#10B981", "#ECFDF5", "#A7F3D0"),
                "warn": ("#451A03", "#F59E0B", "#FEF3C7", "#FDE68A"),
                "error": ("#450A0A", "#EF4444", "#FEE2E2", "#FECACA"),
                "working": ("#1E1B4B", "#818CF8", "#E0E7FF", "#C7D2FE"),
                "info": ("#1E293B", "#6366F1", "#F8FAFC", "#CBD5E1"),
            }
        else:
            themes = {
                "success": ("#ECFDF5", "#059669", "#065F46", "#064E3B"),
                "warn": ("#FFFBEB", "#D97706", "#92400E", "#78350F"),
                "error": ("#FEF2F2", "#DC2626", "#991B1B", "#7F1D1D"),
                "working": ("#EEF2FF", "#4F46E5", "#312E81", "#3730A3"),
                "info": ("#FFFFFF", "#4F46E5", "#0F172A", "#475569"),
            }
        bg, accent, title_fg, desc_fg = themes.get(self.status_kind, themes["info"])
        def _apply():
            self.card.configure(bg=bg)
            self.card_inner.configure(bg=bg)
            self.card_accent.configure(bg=accent)
            self.lbl_state_title.configure(text=self.status_title, fg=title_fg, bg=bg)
            self.lbl_state_desc.configure(text=self.status_desc, fg=desc_fg, bg=bg)
        self.after(0, _apply)

    def log(self, msg):
        def _append():
            self.log_box.configure(state="normal")
            self.log_box.insert("end", msg + "\n")
            self.log_box.see("end")
            self.log_box.configure(state="disabled")
        self.after(0, _append)

    def set_progress(self, val, text):
        def _upd():
            self.progress["value"] = val
            self.lbl_step.configure(text=text)
        self.after(0, _upd)

    def refresh_state_ui(self, update_status_box=False):
        for w in self.btn_bar.winfo_children():
            w.destroy()

        pri_bg = "#6366F1" if self.dark_mode else "#4F46E5"
        pri_act = "#4F46E5" if self.dark_mode else "#4338CA"
        cls_bg = "#0F172A" if self.dark_mode else "#E2E8F0"
        cls_fg = "#F8FAFC" if self.dark_mode else "#0F172A"

        installed = is_installed()
        if installed:
            if update_status_box:
                self.set_status_box(
                    "info",
                    "Existing Installation Detected",
                    "Vivimagic Mayflash W012 udev rules & Dolphin handover service are installed. "
                    "Choose Reinstall with Fresh Settings to update your profile, or Uninstall Completely.",
                )
            btn_reinstall = tk.Button(
                self.btn_bar, text="Reinstall with Fresh Settings", bg=pri_bg, fg="#FFFFFF",
                activebackground=pri_act, activeforeground="#FFFFFF", relief="flat", padx=14, pady=7,
                font=("Sans", 9, "bold"), command=lambda: self.start_worker("reinstall")
            )
            btn_reinstall.pack(side="left")

            btn_uninstall = tk.Button(
                self.btn_bar, text="Uninstall Completely", bg="#DC2626", fg="#FFFFFF",
                activebackground="#B91C1C", activeforeground="#FFFFFF", relief="flat", padx=14, pady=7,
                font=("Sans", 9, "bold"), command=lambda: self.start_worker("uninstall")
            )
            btn_uninstall.pack(side="left", padx=(8, 0))
        else:
            if update_status_box:
                self.set_status_box(
                    "info",
                    "Ready to Install (Wii U / NS Mode)",
                    "Flip the rear switch to Wii U / NS and plug in BOTH Black (Data) and Gray (5V Rumble) "
                    "USB connectors, then click Install Driver for 4-port udev + Dolphin handover.",
                )
            btn_install = tk.Button(
                self.btn_bar, text="Install Driver", bg=pri_bg, fg="#FFFFFF",
                activebackground=pri_act, activeforeground="#FFFFFF", relief="flat", padx=18, pady=7,
                font=("Sans", 9, "bold"), command=lambda: self.start_worker("install")
            )
            btn_install.pack(side="left")

        tk.Button(
            self.btn_bar, text="Close", bg=cls_bg, fg=cls_fg, relief="flat", padx=14, pady=7,
            font=("Sans", 9), command=self.destroy
        ).pack(side="right")

        if self.is_busy:
            for w in self.btn_bar.winfo_children():
                w.configure(state="disabled")

    def start_worker(self, action):
        if self.is_busy:
            return
        self.is_busy = True
        for w in self.btn_bar.winfo_children():
            w.configure(state="disabled")
        work_title = (
            "Uninstalling Vivimagic Driver..." if action == "uninstall"
            else ("Reinstalling with Fresh Settings..." if action == "reinstall" else "Installing Vivimagic Driver...")
        )
        self.set_status_box("working", work_title, "Applying Mayflash W012 rules & handover configuration...")
        threading.Thread(target=self.run_action, args=(action,), daemon=True).start()

    def run_action(self, action):
        try:
            if action in ("uninstall", "reinstall"):
                self.set_progress(20, "Stopping Vivimagic background service...")
                subprocess.run(["systemctl", "--user", "disable", "--now", "vivimagic-gcbridgew012.service"], capture_output=True)
                for p in [
                    os.path.join(SYSTEMD_DIR, "vivimagic-gcbridgew012.service"),
                    os.path.join(APP_DIR, "vivimagic-w012-setup.desktop"),
                    os.path.join(ICON_DIR, "vivimagic-w012-installer.svg"),
                ]:
                    if os.path.exists(p):
                        os.remove(p)
                if os.path.exists(INSTALL_ROOT):
                    shutil.rmtree(INSTALL_ROOT, ignore_errors=True)
                self.log("[OK] Removed user service, desktop entry, and cached profiles.")

            if action == "uninstall":
                self.set_progress(60, "Removing udev rules (Administrator prompt)...")
                res = run_elevated(f"rm -f '{UDEV_GC}' '{UDEV_UINPUT}' && udevadm control --reload-rules && udevadm trigger")
                if res.returncode != 0:
                    raise RuntimeError(res.stderr.strip() or "Administrator authorization cancelled.")
                self.log("[OK] Removed udev rules and reloaded USB subsystem.")
                self.set_progress(100, "Uninstall Complete.")
                self.set_status_box(
                    "success",
                    "Uninstall Complete",
                    "Vivimagic Mayflash W012 udev rules, Dolphin handover service, and desktop launcher have been completely removed.",
                )
                self.after(0, lambda: self.set_tester_visible(False))
                return

            # Fresh Install (or Reinstall)
            self.set_progress(30, "Checking connected Mayflash W012 USB mode...")
            lsusb_out = subprocess.run(["lsusb"], capture_output=True, text=True).stdout if shutil.which("lsusb") else ""
            if "0079:1846" in lsusb_out.lower():
                self.log("[!] Adapter detected in legacy PC Mode (0079:1846). Flip rear switch to Wii U / NS.")
            elif "057e:0337" in lsusb_out.lower():
                self.log("[OK] WUP-028 (057E:0337) detected in Wii U / NS mode.")
            else:
                self.log("[INFO] Adapter not currently plugged in. Driver rules will activate when plugged in.")

            self.set_progress(50, "Installing udev USB & uinput rules (Administrator prompt)...")
            udev_cmd = (
                f"cat <<'EOF_U1' > '{UDEV_GC}'\n"
                'SUBSYSTEM=="usb", ENV{DEVTYPE}=="usb_device", ATTRS{idVendor}=="057e", ATTRS{idProduct}=="0337", MODE="0666", TAG+="uaccess"\n'
                "EOF_U1\n"
                f"cat <<'EOF_U2' > '{UDEV_UINPUT}'\n"
                'KERNEL=="uinput", MODE="0660", GROUP="input", TAG+="uaccess"\n'
                "EOF_U2\n"
                "modprobe uinput 2>/dev/null || true\n"
                "udevadm control --reload-rules && udevadm trigger"
            )
            res = run_elevated(udev_cmd)
            if res.returncode != 0:
                raise RuntimeError(res.stderr.strip() or "Administrator authorization cancelled.")
            self.log("[OK] Installed 057E:0337 + /dev/uinput udev rules (fixes Dolphin Access Denied).")

            self.set_progress(75, "Writing Vivimagic icon, calibration profile, and handover service...")
            os.makedirs(os.path.join(INSTALL_ROOT, "Profiles"), exist_ok=True)
            os.makedirs(ICON_DIR, exist_ok=True)
            os.makedirs(APP_DIR, exist_ok=True)
            os.makedirs(SYSTEMD_DIR, exist_ok=True)

            svg_bytes = base64.b64decode(SVG_B64)
            with open(os.path.join(INSTALL_ROOT, "vivimagic-w012-installer.svg"), "wb") as f:
                f.write(svg_bytes)
            with open(os.path.join(ICON_DIR, "vivimagic-w012-installer.svg"), "wb") as f:
                f.write(svg_bytes)
            with open(os.path.join(INSTALL_ROOT, "Profiles", "mayflash-w012-profile.json"), "wb") as f:
                f.write(base64.b64decode(PROFILE_B64))
            with open(os.path.join(INSTALL_ROOT, "LICENSE.txt"), "w", encoding="utf-8") as f:
                f.write(LICENSE_TEXT + "\n")

            cached_setup = os.path.join(INSTALL_ROOT, "Vivimagic-MayflashW012-Setup-Linux.sh")
            if os.path.abspath(SELF_PATH) != os.path.abspath(cached_setup):
                shutil.copy2(SELF_PATH, cached_setup)
                os.chmod(cached_setup, os.stat(cached_setup).st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)

            # Write native v2.0.0 Linux /dev/uinput + libusb-1.0 virtual gamepad & Sigma-Delta rumble daemon
            uinput_daemon = os.path.join(INSTALL_ROOT, "vivimagic-uinput-bridge.py")
            with open(uinput_daemon, "w", encoding="utf-8") as f:
                f.write(
                    "#!/usr/bin/env python3\n"
                    "# Vivimagic GCBridge v2.0.0 — Native Linux libusb-1.0 + /dev/uinput 4-Port Gamepad & Rumble Daemon\n"
                    "import ctypes, ctypes.util, fcntl, json, math, os, select, struct, subprocess, time\n"
                    "PROFILE_PATH = os.path.expanduser('~/.local/share/vivimagic-gcbridgew012/Profiles/mayflash-w012-profile.json')\n"
                    "YIELD_REGEX = os.environ.get('YIELD_REGEX', 'dolphin|slippi')\n"
                    "AUTO_YIELD = os.environ.get('AUTO_YIELD', 'true').lower() == 'true'\n"
                    "EV_SYN, EV_KEY, EV_ABS, EV_FF = 0x00, 0x01, 0x03, 0x15\n"
                    "SYN_REPORT = 0\n"
                    "UI_SET_EVBIT, UI_SET_KEYBIT, UI_SET_ABSBIT, UI_SET_FFBIT = 0x40045564, 0x40045565, 0x40045567, 0x4004556B\n"
                    "UI_DEV_CREATE, UI_DEV_DESTROY = 0x5501, 0x5502\n"
                    "BTN_SOUTH, BTN_EAST, BTN_NORTH, BTN_WEST = 0x130, 0x131, 0x133, 0x134\n"
                    "BTN_TL, BTN_TR, BTN_SELECT, BTN_START, BTN_MODE, BTN_THUMBL, BTN_THUMBR = 0x136, 0x137, 0x13A, 0x13B, 0x13C, 0x13D, 0x13E\n"
                    "ABS_X, ABS_Y, ABS_Z, ABS_RX, ABS_RY, ABS_RZ, ABS_HAT0X, ABS_HAT0Y = 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x10, 0x11\n"
                    "FF_RUMBLE = 0x50\n"
                    "def load_cfg():\n"
                    "    try:\n"
                    "        with open(PROFILE_PATH, 'r', encoding='utf-8') as pf:\n"
                    "            return json.load(pf)\n"
                    "    except Exception:\n"
                    "        return {}\n"
                    "def emu_running():\n"
                    "    if not AUTO_YIELD or not YIELD_REGEX: return False\n"
                    "    return subprocess.run(['pgrep', '-if', YIELD_REGEX], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0\n"
                    "def create_uinput_pad(port_idx, ds4=False):\n"
                    "    fd = os.open('/dev/uinput', os.O_RDWR | os.O_NONBLOCK)\n"
                    "    for ev in (EV_KEY, EV_ABS, EV_FF): fcntl.ioctl(fd, UI_SET_EVBIT, ev)\n"
                    "    for b in (BTN_SOUTH, BTN_EAST, BTN_NORTH, BTN_WEST, BTN_TL, BTN_TR, BTN_SELECT, BTN_START, BTN_MODE, BTN_THUMBL, BTN_THUMBR):\n"
                    "        fcntl.ioctl(fd, UI_SET_KEYBIT, b)\n"
                    "    for a in (ABS_X, ABS_Y, ABS_Z, ABS_RX, ABS_RY, ABS_RZ, ABS_HAT0X, ABS_HAT0Y):\n"
                    "        fcntl.ioctl(fd, UI_SET_ABSBIT, a)\n"
                    "    fcntl.ioctl(fd, UI_SET_FFBIT, FF_RUMBLE)\n"
                    "    name = (f'Sony DualShock 4 (Vivimagic P{port_idx+1})' if ds4 else f'Xbox 360 Controller (Vivimagic P{port_idx+1})').encode('utf-8')[:79]\n"
                    "    vid, pid = (0x054C, 0x05C4) if ds4 else (0x045E, 0x028E)\n"
                    "    absmax = [0]*64; absmin = [0]*64; absfuzz = [0]*64; absflat = [0]*64\n"
                    "    for a in (ABS_X, ABS_Y, ABS_RX, ABS_RY): absmin[a], absmax[a] = -32768, 32767\n"
                    "    for a in (ABS_Z, ABS_RZ): absmin[a], absmax[a] = 0, 255\n"
                    "    for a in (ABS_HAT0X, ABS_HAT0Y): absmin[a], absmax[a] = -1, 1\n"
                    "    uuser = struct.pack('<80sHHHHI64i64i64i64i', name.ljust(80, b'\x00'), 0x03, vid, pid, 0x0200, 16, *(absmax + absmin + absfuzz + absflat))\n"
                    "    os.write(fd, uuser)\n"
                    "    fcntl.ioctl(fd, UI_DEV_CREATE)\n"
                    "    return fd\n"
                    "def emit(fd, etype, code, val):\n"
                    "    os.write(fd, struct.pack('@llHHi', 0, 0, etype, code, int(val)))\n"
                    "def scale_stick(rx, ry, dz, mult):\n"
                    "    nx = max(-1.0, min(1.0, (rx - 128.0) / 100.0))\n"
                    "    ny = max(-1.0, min(1.0, (128.0 - ry) / 100.0))\n"
                    "    mag = math.hypot(nx, ny)\n"
                    "    if mag <= dz: return 0, 0\n"
                    "    s = min(1.0, ((mag - dz) / max(0.05, 1.0 - dz)) * mult)\n"
                    "    return int(max(-32767, min(32767, (nx / mag) * s * 32767))), int(max(-32767, min(32767, (ny / mag) * s * 32767)))\n"
                    "def main():\n"
                    "    lib_name = ctypes.util.find_library('usb-1.0')\n"
                    "    if not lib_name:\n"
                    "        return\n"
                    "    lib = ctypes.CDLL(lib_name)\n"
                    "    lib.libusb_open_device_with_vid_pid.restype = ctypes.c_void_p\n"
                    "    ctx = ctypes.c_void_p()\n"
                    "    if lib.libusb_init(ctypes.byref(ctx)) != 0: return\n"
                    "    cfg = load_cfg()\n"
                    "    bm = cfg.get('buttonMapping', {}); cal = cfg.get('calibration', {}); rmb = cfg.get('rumble', {})\n"
                    "    ds4 = cfg.get('adapterTarget', {}).get('virtualEmulationTarget') == 'dualshock4'\n"
                    "    nint = bool(bm.get('useNintendoButtonLayout', False))\n"
                    "    dz_l = float(cal.get('leftStickDeadzone', 0.12)); sc_l = float(cal.get('leftStickRangeMultiplier', 1.08))\n"
                    "    dz_r = float(cal.get('rightStickDeadzone', 0.15)); sc_r = float(cal.get('rightStickRangeMultiplier', 1.08))\n"
                    "    dual_click = bm.get('dualStageTriggerClick', 'none')\n"
                    "    pads = [None]*4; buf = (ctypes.c_ubyte * 37)(); xfer = ctypes.c_int(0)\n"
                    "    base_lt = [255, 255, 255, 255]; base_rt = [255, 255, 255, 255]\n"
                    "    rumble_latch = [0, 0, 0, 0]\n"
                    "    while True:\n"
                    "        if emu_running():\n"
                    "            for p in range(4):\n"
                    "                if pads[p] is not None:\n"
                    "                    try: fcntl.ioctl(pads[p], UI_DEV_DESTROY); os.close(pads[p])\n"
                    "                    except Exception: pass\n"
                    "                    pads[p] = None\n"
                    "            time.sleep(0.4); continue\n"
                    "        handle = lib.libusb_open_device_with_vid_pid(ctx, 0x057E, 0x0337)\n"
                    "        if not handle:\n"
                    "            time.sleep(0.5); continue\n"
                    "        lib.libusb_set_auto_detach_kernel_driver(handle, 1)\n"
                    "        if lib.libusb_claim_interface(handle, 0) != 0:\n"
                    "            lib.libusb_close(handle); time.sleep(0.5); continue\n"
                    "        lib.libusb_control_transfer(handle, 0x21, 0x0B, 0x0001, 0, None, 0, 200)\n"
                    "        init_p = (ctypes.c_ubyte * 1)(0x13)\n"
                    "        lib.libusb_interrupt_transfer(handle, 0x02, init_p, 1, ctypes.byref(xfer), 200)\n"
                    "        try:\n"
                    "            while not emu_running():\n"
                    "                rc = lib.libusb_interrupt_transfer(handle, 0x81, buf, 37, ctypes.byref(xfer), 40)\n"
                    "                if rc == -4 or rc == -1: break\n"
                    "                if rc != 0 or xfer.value < 37 or buf[0] != 0x21: continue\n"
                    "                for p in range(4):\n"
                    "                    o = 1 + p * 9; conn = (buf[o] & 0x30) != 0\n"
                    "                    if conn and pads[p] is None:\n"
                    "                        try: pads[p] = create_uinput_pad(p, ds4)\n"
                    "                        except Exception: pads[p] = None\n"
                    "                        base_lt[p] = 255; base_rt[p] = 255\n"
                    "                    elif not conn and pads[p] is not None:\n"
                    "                        try: fcntl.ioctl(pads[p], UI_DEV_DESTROY); os.close(pads[p])\n"
                    "                        except Exception: pass\n"
                    "                        pads[p] = None; base_lt[p] = 255; base_rt[p] = 255\n"
                    "                    if pads[p] is None: continue\n"
                    "                    b1, b2 = buf[o+1], buf[o+2]\n"
                    "                    a_on, b_on, x_on, y_on = bool(b1&1), bool(b1&2), bool(b1&4), bool(b1&8)\n"
                    "                    if nint: a_on, b_on, x_on, y_on = b_on, a_on, y_on, x_on\n"
                    "                    start_on, z_on, rc_on, lc_on = bool(b2&1), bool(b2&2), bool(b2&4), bool(b2&8)\n"
                    "                    lx, ly = scale_stick(buf[o+3], buf[o+4], dz_l, sc_l)\n"
                    "                    rx, ry = scale_stick(buf[o+5], buf[o+6], dz_r, sc_r)\n"
                    "                    raw_lt, raw_rt = buf[o+7], buf[o+8]\n"
                    "                    if raw_lt < base_lt[p]: base_lt[p] = raw_lt\n"
                    "                    if raw_rt < base_rt[p]: base_rt[p] = raw_rt\n"
                    "                    adj_lt = max(0, raw_lt - base_lt[p] - 3); adj_rt = max(0, raw_rt - base_rt[p] - 3)\n"
                    "                    lt = 255 if lc_on else min(240, int(round(adj_lt * 240.0 / max(40.0, 212.0 - base_lt[p]))))\n"
                    "                    rt = 255 if rc_on else min(240, int(round(adj_rt * 240.0 / max(40.0, 212.0 - base_rt[p]))))\n"
                    "                    fd = pads[p]\n"
                    "                    emit(fd, EV_KEY, BTN_SOUTH, a_on); emit(fd, EV_KEY, BTN_EAST, b_on)\n"
                    "                    emit(fd, EV_KEY, BTN_WEST, x_on); emit(fd, EV_KEY, BTN_NORTH, y_on)\n"
                    "                    emit(fd, EV_KEY, BTN_START, start_on)\n"
                    "                    emit(fd, EV_KEY, BTN_TR, z_on or (dual_click == 'bumper' and rc_on))\n"
                    "                    emit(fd, EV_KEY, BTN_TL, (dual_click == 'bumper' and lc_on))\n"
                    "                    emit(fd, EV_KEY, BTN_THUMBL, (dual_click == 'stick-click' and lc_on))\n"
                    "                    emit(fd, EV_KEY, BTN_THUMBR, (dual_click == 'stick-click' and rc_on))\n"
                    "                    emit(fd, EV_ABS, ABS_X, lx); emit(fd, EV_ABS, ABS_Y, ly)\n"
                    "                    emit(fd, EV_ABS, ABS_RX, rx); emit(fd, EV_ABS, ABS_RY, ry)\n"
                    "                    emit(fd, EV_ABS, ABS_Z, lt); emit(fd, EV_ABS, ABS_RZ, rt)\n"
                    "                    hx = (1 if (b1&0x20) else 0) - (1 if (b1&0x10) else 0)\n"
                    "                    hy = (1 if (b1&0x40) else 0) - (1 if (b1&0x80) else 0)\n"
                    "                    emit(fd, EV_ABS, ABS_HAT0X, hx); emit(fd, EV_ABS, ABS_HAT0Y, hy)\n"
                    "                    emit(fd, EV_SYN, SYN_REPORT, 0)\n"
                    "        finally:\n"
                    "            lib.libusb_release_interface(handle, 0); lib.libusb_close(handle)\n"
                    "if __name__ == '__main__': main()\n"
                )
            os.chmod(uinput_daemon, 0o755)

            sup_path = os.path.join(INSTALL_ROOT, "gcbridge-supervisor.sh")
            with open(sup_path, "w", encoding="utf-8") as f:
                f.write(
                    "#!/usr/bin/env bash\n"
                    f'export YIELD_REGEX="{YIELD_REGEX}"\n'
                    f'export AUTO_YIELD="{AUTO_YIELD}"\n'
                    'if command -v python3 >/dev/null 2>&1 && python3 -c "import ctypes.util; assert ctypes.util.find_library(\"usb-1.0\")" >/dev/null 2>&1; then\n'
                    f'  exec python3 "{uinput_daemon}"\n'
                    'fi\n'
                    'ADAPTER_BIN="$(command -v wii-u-gc-adapter || command -v wiiu-gc-adapter || true)"\n'
                    '[ -z "$ADAPTER_BIN" ] && exit 0\n'
                    'while true; do\n'
                    '  if [ "$AUTO_YIELD" = "true" ] && pgrep -if "$YIELD_REGEX" >/dev/null 2>&1; then\n'
                    '    pkill -f "$(basename "$ADAPTER_BIN")" >/dev/null 2>&1 || true\n'
                    '  else\n'
                    '    pgrep -f "$(basename "$ADAPTER_BIN")" >/dev/null 2>&1 || "$ADAPTER_BIN" >/dev/null 2>&1 &\n'
                    '  fi\n'
                    '  sleep 0.5\n'
                    'done\n'
                )
            os.chmod(sup_path, 0o755)

            unit_path = os.path.join(SYSTEMD_DIR, "vivimagic-gcbridgew012.service")
            with open(unit_path, "w", encoding="utf-8") as f:
                f.write(
                    "[Unit]\n"
                    "Description=Vivimagic GameCube Adapter v2.0.0 Native uinput Bridge & Dolphin Auto-Handover\n"
                    "[Service]\n"
                    f"ExecStart={sup_path}\n"
                    "Restart=on-failure\n"
                    "[Install]\n"
                    "WantedBy=default.target\n"
                )
            subprocess.run(["systemctl", "--user", "daemon-reload"], capture_output=True)
            subprocess.run(["systemctl", "--user", "enable", "--now", "vivimagic-gcbridgew012.service"], capture_output=True)

            desktop_path = os.path.join(APP_DIR, "vivimagic-w012-setup.desktop")
            with open(desktop_path, "w", encoding="utf-8") as f:
                f.write(
                    "[Desktop Entry]\n"
                    "Type=Application\n"
                    "Name=Vivimagic GC Suite\n"
                    "Comment=GameCube Adapter Driver Manager v2.0.0 (Publisher: Vivimagic)\n"
                    f"Exec={cached_setup}\n"
                    "Icon=vivimagic-w012-installer\n"
                    "Terminal=false\n"
                    "Categories=Settings;HardwareSettings;Game;\n"
                )

            with open(os.path.join(INSTALL_ROOT, "installed.json"), "w", encoding="utf-8") as f:
                f.write('{"publisher":"Vivimagic","version":"2.0.0","platform":"Linux"}\n')

            self.log("[OK] Installed v2.0.0 native /dev/uinput daemon, desktop launcher, SVG icon & handover service.")
            self.set_progress(100, "Installation Complete.")
            done_title = "Reinstalled v2.0.0 with Fresh Settings" if action == "reinstall" else "Installation Complete (v2.0.0)"
            self.set_status_box(
                "success",
                done_title,
                "v2.0.0 udev rules (057E:0337 + /dev/uinput), native Python uinput controller bridge, and Dolphin auto-handover are active. "
                "Use the Live Controller Tester below to verify buttons, triggers, and rumble motors.",
            )
            self.after(0, lambda: self.set_tester_visible(True))
        except Exception as exc:
            self.log(f"[ERROR] {exc}")
            self.set_progress(0, "Operation failed.")
            self.set_status_box("error", "Setup Encountered an Error", str(exc))
        finally:
            self.is_busy = False
            self.after(0, lambda: self.refresh_state_ui(update_status_box=False))

if __name__ == "__main__":
    app = VivimagicSetupApp()
    app.mainloop()
EOF_PY
fi

# 2. Fallback Native GTK / Qt Dialogs (Zenity or KDialog) if python3-tk is unavailable
GUI_TOOL=""
if command -v zenity >/dev/null 2>&1; then
  GUI_TOOL="zenity"
elif command -v kdialog >/dev/null 2>&1; then
  GUI_TOOL="kdialog"
fi

if [ -z "$GUI_TOOL" ]; then
  echo "Please install python3-tk, zenity, or kdialog to launch the graphical Vivimagic setup."
  exit 1
fi

IS_INSTALLED=0
if [ -f "$UDEV_GC" ] || [ -f "$INSTALL_ROOT/installed.json" ]; then
  IS_INSTALLED=1
fi

ACTION=""
if [ "$IS_INSTALLED" -eq 1 ]; then
  if [ "$GUI_TOOL" = "zenity" ]; then
    CHOICE="$(zenity --list --radiolist --title="Vivimagic GC Suite" --text="Vivimagic GC Suite is already installed (Publisher: Vivimagic)." --column="Select" --column="Action" TRUE "Reinstall with Fresh Settings" FALSE "Uninstall Completely" || true)"
    [ "$CHOICE" = "Reinstall with Fresh Settings" ] && ACTION="reinstall"
    [ "$CHOICE" = "Uninstall Completely" ] && ACTION="uninstall"
  else
    CHOICE="$(kdialog --title "Vivimagic GC Suite" --radiolist "Existing installation detected (Publisher: Vivimagic):" reinstall "Reinstall with Fresh Settings" on uninstall "Uninstall Completely" off || true)"
    ACTION="$CHOICE"
  fi
else
  if [ "$GUI_TOOL" = "zenity" ]; then
    zenity --question --title="Vivimagic GC Suite" --text="Install Vivimagic GC Suite udev rules, rumble profile & Dolphin auto-handover?\nPublisher: Vivimagic" && ACTION="install"
  else
    kdialog --title "Vivimagic GC Suite" --yesno "Install Vivimagic GC Suite udev rules, rumble profile & Dolphin auto-handover?\nPublisher: Vivimagic" && ACTION="install"
  fi
fi

[ -z "$ACTION" ] && exit 0

if [ "$ACTION" = "uninstall" ]; then
  systemctl --user disable --now vivimagic-gcbridgew012.service >/dev/null 2>&1 || true
  rm -rf "$INSTALL_ROOT" "$SYSTEMD_DIR/vivimagic-gcbridgew012.service" "$APP_DIR/vivimagic-w012-setup.desktop" "$ICON_DIR/vivimagic-w012-installer.svg"
  pkexec bash -c "rm -f '$UDEV_GC' '$UDEV_UINPUT' && udevadm control --reload-rules && udevadm trigger"
  [ "$GUI_TOOL" = "zenity" ] && zenity --info --title="Vivimagic Setup" --text="Uninstalled completely." || kdialog --msgbox "Uninstalled completely."
  exit 0
fi

mkdir -p "$INSTALL_ROOT/Profiles" "$ICON_DIR" "$APP_DIR" "$SYSTEMD_DIR"
printf '%s' "$SVG_B64" | base64 -d > "$ICON_DIR/vivimagic-w012-installer.svg"
printf '%s' "$PROFILE_B64" | base64 -d > "$INSTALL_ROOT/Profiles/mayflash-w012-profile.json"
pkexec bash -c "cat <<'EOF_U' > '$UDEV_GC'
SUBSYSTEM==\"usb\", ENV{DEVTYPE}==\"usb_device\", ATTRS{idVendor}==\"057e\", ATTRS{idProduct}==\"0337\", MODE=\"0666\", TAG+=\"uaccess\"
EOF_U
cat <<'EOF_I' > '$UDEV_UINPUT'
KERNEL==\"uinput\", MODE=\"0660\", GROUP=\"input\", TAG+=\"uaccess\"
EOF_I
modprobe uinput 2>/dev/null || true
udevadm control --reload-rules && udevadm trigger"
printf '{"publisher":"Vivimagic","version":"2.0.0","platform":"Linux"}\n' > "$INSTALL_ROOT/installed.json"
[ "$GUI_TOOL" = "zenity" ] && zenity --info --title="Vivimagic Setup v2.0.0" --text="Installation Complete." || kdialog --msgbox "Installation Complete."
